echo "========== SECTION 2: ADD PROVIDER-NEUTRAL BOUNDED PLANNING CONTRACT =========="
"$PY" - <<'PY'
from pathlib import Path

root = Path('/home/al/projects/jason')
module = root / 'implementation/orchestrator/semantic_intent_planning_loop.py'
tests = root / 'implementation/orchestrator/tests/test_semantic_intent_planning_loop.py'

module.write_text('''from __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any, Mapping, Protocol, Sequence\n\n\n_ALLOWED_CONTEXT_VIEWS = frozenset({\n    "semantic_knowledge",\n    "capability_registry",\n    "system_registry",\n    "evidence_catalog",\n    "derivation_registry",\n})\n\n_FORBIDDEN_PLAN_KEYS = frozenset({\n    "provider",\n    "provider_name",\n    "connector",\n    "connector_name",\n    "tool",\n    "tool_name",\n    "agent",\n    "target_agent",\n    "shell",\n    "command",\n    "url",\n    "credential",\n    "credentials",\n    "secret",\n})\n\n\n@dataclass(frozen=True, slots=True)\nclass IntentPlanningBudget:\n    max_iterations: int = 6\n    max_context_requests: int = 6\n\n    def __post_init__(self) -> None:\n        if not (1 <= self.max_iterations <= 20):\n            raise ValueError("max_iterations must be between 1 and 20")\n        if not (0 <= self.max_context_requests <= 20):\n            raise ValueError("max_context_requests must be between 0 and 20")\n\n\n@dataclass(frozen=True, slots=True)\nclass PlanningContextRequest:\n    view: str\n    query: Mapping[str, Any] = field(default_factory=dict)\n    purpose: str = ""\n\n    def __post_init__(self) -> None:\n        if self.view not in _ALLOWED_CONTEXT_VIEWS:\n            raise PermissionError(f"planning context view is not governed: {self.view}")\n        _reject_forbidden_keys(self.query)\n\n\n@dataclass(frozen=True, slots=True)\nclass FulfillmentPlanStepCandidate:\n    capability_name: str\n    purpose: str\n    required_facts: tuple[str, ...] = ()\n    expected_evidence: tuple[str, ...] = ()\n\n    def __post_init__(self) -> None:\n        if not self.capability_name.strip():\n            raise ValueError("capability_name is required")\n        if not self.purpose.strip():\n            raise ValueError("plan step purpose is required")\n\n\n@dataclass(frozen=True, slots=True)\nclass FulfillmentPlanCandidate:\n    steps: tuple[FulfillmentPlanStepCandidate, ...]\n    rationale_summary: str\n    unresolved_requirements: tuple[str, ...] = ()\n\n    def __post_init__(self) -> None:\n        if not self.steps and not self.unresolved_requirements:\n            raise ValueError("plan must contain steps or unresolved requirements")\n        if not self.rationale_summary.strip():\n            raise ValueError("plan rationale summary is required")\n\n\n@dataclass(frozen=True, slots=True)\nclass PlanningTurn:\n    status: str\n    context_request: PlanningContextRequest | None = None\n    plan: FulfillmentPlanCandidate | None = None\n    gap_summary: str | None = None\n\n    def __post_init__(self) -> None:\n        if self.status not in {"request_context", "propose_plan", "declare_gap"}:\n            raise ValueError("planning turn status is invalid")\n        if self.status == "request_context" and self.context_request is None:\n            raise ValueError("request_context turn requires context_request")\n        if self.status == "propose_plan" and self.plan is None:\n            raise ValueError("propose_plan turn requires plan")\n        if self.status == "declare_gap" and not str(self.gap_summary or "").strip():\n            raise ValueError("declare_gap turn requires gap_summary")\n\n\n@dataclass(frozen=True, slots=True)\nclass PlanningTraceEntry:\n    iteration: int\n    status: str\n    context_view: str | None = None\n\n\n@dataclass(frozen=True, slots=True)\nclass IntentPlanningOutcome:\n    status: str\n    plan: FulfillmentPlanCandidate | None\n    gap_summary: str | None\n    trace: tuple[PlanningTraceEntry, ...]\n    iterations_used: int\n    context_requests_used: int\n\n\nclass SemanticIntentPlanningReasoner(Protocol):\n    def next_turn(\n        self,\n        *,\n        intent: Mapping[str, Any],\n        context: Mapping[str, Any],\n        history: Sequence[PlanningTraceEntry],\n    ) -> PlanningTurn: ...\n\n\nclass GovernedPlanningContextReader(Protocol):\n    def read(\n        self,\n        *,\n        request: PlanningContextRequest,\n        intent: Mapping[str, Any],\n    ) -> Mapping[str, Any]: ...\n\n\n@dataclass(frozen=True, slots=True)\nclass BoundedSemanticIntentPlanningLoop:\n    reasoner: SemanticIntentPlanningReasoner\n    context_reader: GovernedPlanningContextReader\n    budget: IntentPlanningBudget = IntentPlanningBudget()\n\n    def plan(self, *, intent: Mapping[str, Any]) -> IntentPlanningOutcome:\n        _reject_forbidden_keys(intent)\n        context: dict[str, Any] = {}\n        trace: list[PlanningTraceEntry] = []\n        context_requests = 0\n\n        for iteration in range(1, self.budget.max_iterations + 1):\n            turn = self.reasoner.next_turn(\n                intent=dict(intent),\n                context=dict(context),\n                history=tuple(trace),\n            )\n\n            if turn.status == "request_context":\n                assert turn.context_request is not None\n                if context_requests >= self.budget.max_context_requests:\n                    return IntentPlanningOutcome(\n                        status="budget_exhausted",\n                        plan=None,\n                        gap_summary="planning context-request budget exhausted",\n                        trace=tuple(trace),\n                        iterations_used=iteration,\n                        context_requests_used=context_requests,\n                    )\n                request = turn.context_request\n                snapshot = self.context_reader.read(request=request, intent=dict(intent))\n                _reject_forbidden_keys(snapshot)\n                context_requests += 1\n                context[request.view] = dict(snapshot)\n                trace.append(PlanningTraceEntry(iteration, turn.status, request.view))\n                continue\n\n            if turn.status == "propose_plan":\n                assert turn.plan is not None\n                _validate_plan_against_governed_capabilities(turn.plan, context)\n                trace.append(PlanningTraceEntry(iteration, turn.status))\n                return IntentPlanningOutcome(\n                    status="planned",\n                    plan=turn.plan,\n                    gap_summary=None,\n                    trace=tuple(trace),\n                    iterations_used=iteration,\n                    context_requests_used=context_requests,\n                )\n\n            trace.append(PlanningTraceEntry(iteration, turn.status))\n            return IntentPlanningOutcome(\n                status="knowledge_gap",\n                plan=None,\n                gap_summary=str(turn.gap_summary),\n                trace=tuple(trace),\n                iterations_used=iteration,\n                context_requests_used=context_requests,\n            )\n\n        return IntentPlanningOutcome(\n            status="budget_exhausted",\n            plan=None,\n            gap_summary="planning iteration budget exhausted",\n            trace=tuple(trace),\n            iterations_used=self.budget.max_iterations,\n            context_requests_used=context_requests,\n        )\n\n\ndef _validate_plan_against_governed_capabilities(\n    plan: FulfillmentPlanCandidate,\n    context: Mapping[str, Any],\n) -> None:\n    capability_snapshot = context.get("capability_registry")\n    if not isinstance(capability_snapshot, Mapping):\n        raise PermissionError("plan cannot be accepted without governed capability-registry context")\n    raw_names = capability_snapshot.get("capability_names", ())\n    if not isinstance(raw_names, (list, tuple, set, frozenset)):\n        raise ValueError("capability registry snapshot must expose capability_names")\n    allowed = {str(item).strip() for item in raw_names if str(item).strip()}\n    for step in plan.steps:\n        if step.capability_name not in allowed:\n            raise PermissionError(\n                f"planning reasoner selected capability outside governed registry: {step.capability_name}"\n            )\n\n\ndef _reject_forbidden_keys(value: Any) -> None:\n    if isinstance(value, Mapping):\n        for raw_key, child in value.items():\n            key = str(raw_key).strip().casefold()\n            if key in _FORBIDDEN_PLAN_KEYS:\n                raise PermissionError(f"planning contract contains prohibited direct-routing field: {raw_key}")\n            _reject_forbidden_keys(child)\n    elif isinstance(value, (list, tuple, set, frozenset)):\n        for child in value:\n            _reject_forbidden_keys(child)\n''', encoding='utf-8')

tests.write_text('''import pytest\n\nfrom orchestrator.semantic_intent_planning_loop import (\n    BoundedSemanticIntentPlanningLoop,\n    FulfillmentPlanCandidate,\n    FulfillmentPlanStepCandidate,\n    IntentPlanningBudget,\n    PlanningContextRequest,\n    PlanningTurn,\n)\n\n\nclass ContextReader:\n    def __init__(self):\n        self.calls = []\n\n    def read(self, *, request, intent):\n        self.calls.append((request, intent))\n        if request.view == "capability_registry":\n            return {"capability_names": ["endpoint.device.search", "endpoint.audit.read"]}\n        if request.view == "semantic_knowledge":\n            return {"concepts": ["operating_system.windows.display_version"]}\n        return {}\n\n\nclass SequencedReasoner:\n    def __init__(self, turns):\n        self.turns = list(turns)\n        self.calls = 0\n\n    def next_turn(self, **kwargs):\n        turn = self.turns[self.calls]\n        self.calls += 1\n        return turn\n\n\ndef test_loop_can_inspect_governed_context_then_propose_registered_capability_plan():\n    reasoner = SequencedReasoner([\n        PlanningTurn(\n            status="request_context",\n            context_request=PlanningContextRequest(\n                view="semantic_knowledge",\n                query={"concept": "operating_system.windows.display_version"},\n                purpose="understand requested concept",\n            ),\n        ),\n        PlanningTurn(\n            status="request_context",\n            context_request=PlanningContextRequest(\n                view="capability_registry",\n                query={"resource_type": "endpoint"},\n                purpose="discover governed fulfillment capabilities",\n            ),\n        ),\n        PlanningTurn(\n            status="propose_plan",\n            plan=FulfillmentPlanCandidate(\n                steps=(FulfillmentPlanStepCandidate(\n                    capability_name="endpoint.device.search",\n                    purpose="acquire governed endpoint evidence",\n                    required_facts=("operating system display version",),\n                ),),\n                rationale_summary="use a registered endpoint read capability",\n            ),\n        ),\n    ])\n    outcome = BoundedSemanticIntentPlanningLoop(\n        reasoner=reasoner,\n        context_reader=ContextReader(),\n    ).plan(intent={"resource_type": "endpoint", "requested_facts": ["operating system display version"]})\n    assert outcome.status == "planned"\n    assert outcome.iterations_used == 3\n    assert outcome.context_requests_used == 2\n    assert outcome.plan is not None\n    assert outcome.plan.steps[0].capability_name == "endpoint.device.search"\n\n\ndef test_loop_rejects_reasoner_capability_not_present_in_governed_registry():\n    reasoner = SequencedReasoner([\n        PlanningTurn(\n            status="request_context",\n            context_request=PlanningContextRequest(view="capability_registry"),\n        ),\n        PlanningTurn(\n            status="propose_plan",\n            plan=FulfillmentPlanCandidate(\n                steps=(FulfillmentPlanStepCandidate(\n                    capability_name="invented.provider.direct.call",\n                    purpose="bad direct route",\n                ),),\n                rationale_summary="invalid",\n            ),\n        ),\n    ])\n    with pytest.raises(PermissionError, match="outside governed registry"):\n        BoundedSemanticIntentPlanningLoop(\n            reasoner=reasoner,\n            context_reader=ContextReader(),\n        ).plan(intent={"resource_type": "endpoint"})\n\n\ndef test_loop_rejects_direct_provider_or_agent_routing_fields():\n    with pytest.raises(PermissionError, match="prohibited direct-routing field"):\n        BoundedSemanticIntentPlanningLoop(\n            reasoner=SequencedReasoner([]),\n            context_reader=ContextReader(),\n        ).plan(intent={"provider": "datto_rmm"})\n    with pytest.raises(PermissionError, match="not governed"):\n        PlanningContextRequest(view="direct_agent")\n\n\ndef test_loop_stops_when_context_request_budget_is_exhausted():\n    repeated = PlanningTurn(\n        status="request_context",\n        context_request=PlanningContextRequest(view="semantic_knowledge"),\n    )\n    outcome = BoundedSemanticIntentPlanningLoop(\n        reasoner=SequencedReasoner([repeated, repeated, repeated]),\n        context_reader=ContextReader(),\n        budget=IntentPlanningBudget(max_iterations=3, max_context_requests=1),\n    ).plan(intent={"resource_type": "endpoint"})\n    assert outcome.status == "budget_exhausted"\n    assert outcome.context_requests_used == 1\n\n\ndef test_loop_can_declare_structured_knowledge_gap_without_inventing_plan():\n    outcome = BoundedSemanticIntentPlanningLoop(\n        reasoner=SequencedReasoner([\n            PlanningTurn(\n                status="declare_gap",\n                gap_summary="no governed fulfillment path is currently known",\n            )\n        ]),\n        context_reader=ContextReader(),\n    ).plan(intent={"resource_type": "invoice", "requested_facts": ["purchase order"]})\n    assert outcome.status == "knowledge_gap"\n    assert outcome.plan is None\n    assert "no governed fulfillment path" in str(outcome.gap_summary)\n''', encoding='utf-8')

print(f'WROTE: {module.relative_to(root)}')
print(f'WROTE: {tests.relative_to(root)}')
PY

